(invitee) => {
            const contactInfo = invitee.invitee.inviteeContactInfo;
            if (request.emailOrPhone === 'email' && contactInfo.invitationType === 'mail') {
                return contactInfo.email?.trim().toLowerCase() === request.value.trim().toLowerCase();
            }
            if (request.emailOrPhone === 'phone' && contactInfo.invitationType === 'phone') {
                return (
                    contactInfo.phoneNumber?.internationalPhoneNumber?.replace(/\s/g, '') ===
                    request.value.replace(/\s/g, '')
                );
            }
            return false;
        }

